const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const output = path.join(root, 'dist', 'interval-cosmos-v2.0.5-complete.sql');

const files = [
  ...Array.from({ length: 8 }, (_, i) => `sql/base-v2.0.5/part-${String(i + 1).padStart(2, '0')}.sql`),
  'sql/avatar-catalog-v2.0.5.sql',
  'sql/device-link-v2.0.5.sql',
  'sql/account-recovery-v2.0.5.sql',
  'sql/progression-v2.0.5.sql',
  'sql/assignments-v2.0.5.sql',
  'sql/assignments-admin-only-v2.0.5.sql',
  'sql/assignments-multimode-v2.0.5.sql',
  'sql/admin-dashboard-v2.0.5.sql',
  'sql/staff-self-registration-v2.0.5.sql',
];

for (const relative of files) {
  const file = path.join(root, relative);
  if (!fs.existsSync(file)) {
    console.error(`ERROR: missing SQL source: ${relative}`);
    process.exit(1);
  }
}

const header = `-- ================================================================\n` +
  `-- INTERVAL COSMOS v2.0.5 — COMPLETE FRESH BUILD\n` +
  `-- Generated by scripts/build-v2.0.5-supabase-bundle.js\n` +
  `-- DO NOT EDIT THIS GENERATED FILE BY HAND.\n` +
  `-- Source order: sql/V2.0.5_MIGRATION_ORDER.md\n` +
  `-- Intended for an EMPTY pre-release verification Supabase project.\n` +
  `-- The Phase 1 base intentionally drops old application objects.\n` +
  `-- ================================================================\n\n`;

const body = files.map((relative, index) => {
  const source = fs.readFileSync(path.join(root, relative), 'utf8');
  return `-- >>> BEGIN ${index + 1}/${files.length}: ${relative}\n${source.trimEnd()}\n-- <<< END ${relative}\n`;
}).join('\n');

fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, header + body + '\n', 'utf8');

const bytes = fs.statSync(output).size;
console.log(`WROTE ${path.relative(root, output)} (${bytes.toLocaleString()} bytes)`);
console.log(`SOURCE FILES: ${files.length}`);
console.log('Next: paste the generated SQL into an EMPTY Supabase test project, then run sql/verify-v2.0.5-fresh-build.sql.');
